import type { Session } from '@supabase/supabase-js';
import { pressEnterInChrome, pressKeyInChrome } from './keyboard';

type Fixture = {
  organizationId: string;
  otherOrganizationId: string;
  name: string;
  asOf: string;
  from: string;
  adminId: string;
  teacherId: string;
  studentId: string;
  entityId: string;
  oracle: {
    total: number;
    foreignTotal: number;
    combinedTotal: number;
    combinedIds: string[];
  };
  filters: {
    actorId: string;
    action: string;
    entityType: string;
    entityId: string;
    from: string;
    asOf: string;
  };
  firstEventId: string;
  nullActorEventId: string;
};
type Context = Fixture & { admin: Session };
type Measurement = {
  organizationId: string;
  firstNavigationMs: number | null;
  firstNavigationValid: boolean;
  samples: { durationMs: number; valid: boolean }[];
  startedAt: number | null;
  index: number;
};
const rows = '[data-cy="audit-row"]';
const ready = '[data-testid="audit-list-ready"]';
let releaseResponse: (() => void) | undefined;
let measurement: Measurement | null = null;
function route(fixture: Fixture) {
  return `/administracion/organizaciones/${fixture.organizationId}/auditoria`;
}
function localField(value: string): string {
  const parts = new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'America/Santiago',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23',
  }).formatToParts(new Date(value));
  const get = (type: string) => parts.find((part) => part.type === type)!.value;
  return `${get('year')}-${get('month')}-${get('day')}T${get('hour')}:${get('minute')}`;
}
function visitAs(
  session: Session,
  target: string,
  beforeLoad?: (window: Cypress.AUTWindow) => void,
) {
  return cy.visit(target, {
    onBeforeLoad(window) {
      window.localStorage.setItem(
        'alunza.auth.127.0.0.1:18421',
        JSON.stringify(session),
      );
      beforeLoad?.(window);
    },
  });
}
function listReady(c: Context) {
  visitAs(c.admin, route(c));
  cy.contains('h1', 'Auditoría').should('be.visible');
  cy.get(ready).should(
    'contain.text',
    `Registros encontrados: ${c.oracle.total}.`,
  );
  cy.get(rows).should('have.length', 20);
  cy.get(rows).first().should('have.attr', 'data-event-id', c.firstEventId);
}
function apply() {
  cy.get('[data-cy="audit-filters"]')
    .contains('button', 'Aplicar filtros')
    .click();
}
function clearFilters() {
  cy.get('[data-cy="audit-filters"]')
    .contains('button', 'Limpiar filtros')
    .click();
}
function nextPage() {
  cy.get('nav[aria-label="Páginas de auditoría"]')
    .contains('button', 'Siguiente página')
    .click();
}
function tabTo(selector: string, remaining = 30) {
  cy.document().then((document) => {
    if (document.activeElement?.matches(selector)) return;
    expect(remaining, `Tab reaches ${selector}`).to.be.greaterThan(0);
    pressKeyInChrome('Tab');
    tabTo(selector, remaining - 1);
  });
}
function recordMeasurement(draft: Measurement) {
  return cy.task<{ samples: number; p95Ms: number; passed: boolean }>(
    'audit:performance',
    {
      organizationId: draft.organizationId,
      firstNavigationMs: draft.firstNavigationMs,
      firstNavigationValid: draft.firstNavigationValid,
      samples: draft.samples,
    },
    { log: false },
  );
}

describe('IMP-06.05 · Consulta administrativa de auditoría', () => {
  beforeEach(function () {
    const profile = this.currentTest?.title.includes('IMP06-AUDIT-08')
      ? 'capacity'
      : 'functional';
    cy.task<Fixture>(
      'audit:prepare',
      { profile },
      { log: false, timeout: 120_000 },
    ).then((fixture) =>
      cy
        .task<Session>('identity:login', 'ADMIN', { log: false })
        .then((admin) =>
          cy.wrap({ ...fixture, admin }, { log: false }).as('audit'),
        ),
    );
  });

  afterEach(function () {
    releaseResponse?.();
    releaseResponse = undefined;
    const draft = measurement;
    measurement = null;
    if (draft && this.currentTest?.state === 'failed') {
      if (draft.startedAt !== null) {
        const durationMs = performance.now() - draft.startedAt;
        if (draft.index === 0) {
          draft.firstNavigationMs = durationMs;
          draft.firstNavigationValid = false;
        } else draft.samples.push({ durationMs, valid: false });
      }
      recordMeasurement(draft);
    }
  });

  it('IMP06-AUDIT-01 · Consultar y filtrar eventos → páginas sin duplicados y corte exacto conservado', () => {
    cy.get<Context>('@audit').then((c) => {
      cy.intercept({
        method: 'GET',
        pathname: `/api/v1/organizations/${c.organizationId}/audit-events`,
      }).as('auditList');
      listReady(c);
      const ids: string[] = [];
      let cut: string;
      cy.wait('@auditList').then(({ response }) => {
        cut = response!.body.data.asOf;
      });
      cy.get(rows).then(($rows) =>
        ids.push(
          ...$rows.toArray().map((row) => row.getAttribute('data-event-id')!),
        ),
      );
      nextPage();
      cy.wait('@auditList').then(({ request, response }) => {
        expect(new URL(request.url).searchParams.get('asOf')).to.equal(cut);
        expect(new URL(request.url).searchParams.has('cursor')).to.equal(true);
        expect(response!.body.data.asOf).to.equal(cut);
      });
      cy.get(rows)
        .should('have.length', 5)
        .then(($rows) => {
          ids.push(
            ...$rows.toArray().map((row) => row.getAttribute('data-event-id')!),
          );
          expect(new Set(ids).size).to.equal(25);
        });
      cy.get(`${rows}[data-event-id="${c.nullActorEventId}"]`).should(
        'contain.text',
        'Sin actor identificado',
      );
      for (const field of [
        'actorId',
        'action',
        'entityType',
        'entityId',
      ] as const)
        cy.get(`[name="${field}"]`).type(c.filters[field]);
      apply();
      cy.wait('@auditList').then(({ request, response }) => {
        const query = new URL(request.url).searchParams;
        expect(query.has('cursor')).to.equal(false);
        expect(query.get('asOf')).to.equal(cut);
        expect(response!.body.data.page.totalFiltered).to.equal(
          c.oracle.combinedTotal,
        );
        expect(
          response!.body.data.items.map(
            (item: { eventId: string }) => item.eventId,
          ),
        ).to.deep.equal(c.oracle.combinedIds);
      });
      cy.get(rows).should('have.length', c.oracle.combinedTotal);
      cy.get('[name="from"]').clear().type(localField(c.from));
      cy.get('[name="asOf"]').clear().type(localField(c.asOf));
      apply();
      cy.wait('@auditList').then(({ request, response }) => {
        const query = new URL(request.url).searchParams;
        expect(Date.parse(query.get('from')!)).to.equal(Date.parse(c.from));
        expect(Date.parse(query.get('asOf')!)).to.equal(Date.parse(c.asOf));
        expect(response!.body.data.page.totalFiltered).to.equal(
          c.oracle.combinedTotal,
        );
        cut = response!.body.data.asOf;
      });
      clearFilters();
      cy.wait('@auditList').then(({ response }) =>
        expect(response!.body.data.asOf).to.equal(cut),
      );
      cy.get(rows).should('have.length', 20);
      cy.contains('button', 'Actualizar auditoría').click();
      cy.wait('@auditList').then(({ request, response }) => {
        expect(new URL(request.url).searchParams.has('asOf')).to.equal(false);
        expect(Date.parse(response!.body.data.asOf)).to.be.at.least(
          Date.parse(cut),
        );
      });
      cy.get(ready)
        .find('a[href*="/intentos/"], a[href*="/estudiantes/"]')
        .should('not.exist');
      cy.contains('button', 'Generar CSV').should('be.visible');
    });
  });

  it('IMP06-AUDIT-02 · Corregir filtros inválidos y consultar sin coincidencias → error y vacío diferenciados', () => {
    cy.get<Context>('@audit').then((c) => {
      listReady(c);
      cy.get('[name="actorId"]').type('actor-invalido');
      apply();
      cy.get('[name="actorId"]')
        .should('have.attr', 'aria-invalid', 'true')
        .and('have.value', 'actor-invalido');
      cy.get(rows).should('have.length', 20);
      cy.get('[name="actorId"]').clear();
      cy.get('[name="from"]').type('2099-01-01T12:00');
      apply();
      cy.get('[name="from"]').should('have.attr', 'aria-invalid', 'true');
      cy.get('[name="from"]').clear();
      cy.get('[name="asOf"]').type('2099-01-01T12:00');
      apply();
      cy.get('[role="alert"]').should('be.visible');
      cy.get(rows).should('not.exist');
      cy.contains('No hay registros para estos filtros.').should('not.exist');
      clearFilters();
      cy.get(rows).should('have.length', 20);
      cy.get('[name="action"]').type('fixture.no_matches');
      apply();
      cy.contains('No hay registros para estos filtros.').should('be.visible');
      cy.get(ready).should('contain.text', 'Registros encontrados: 0.');
      cy.get(rows).should('not.exist');
      clearFilters();
      cy.get(rows).should('have.length', 20);
    });
  });

  it('IMP06-AUDIT-03 · Rol ajeno y revocación → la auditoría desaparece sin revelar otra organización', () => {
    cy.get<Context>('@audit').then((c) => {
      for (const role of ['TEACHER', 'STUDENT'])
        cy.task<Session>('identity:login', role, { log: false }).then(
          (session) => {
            visitAs(session, route(c));
            cy.get('[role="alert"]').should('be.visible');
            cy.get(rows).should('not.exist');
          },
        );
      visitAs(c.admin, route({ ...c, organizationId: c.otherOrganizationId }));
      cy.get('[role="alert"]').should('be.visible');
      cy.get(rows).should('not.exist');
      listReady(c);
      cy.task(
        'audit:revoke',
        { organizationId: c.organizationId, actor: 'admin' },
        { log: false },
      );
      nextPage();
      cy.get('[role="alert"]').should('be.visible');
      cy.get(rows).should('not.exist');
      cy.get('[data-cy="audit-filters"]').should('not.exist');
      cy.task(
        'audit:revoke',
        { organizationId: c.organizationId, actor: 'admin', restore: true },
        { log: false },
      );
      cy.contains('button', 'Volver a comprobar acceso').click();
      cy.get(rows).should('have.length', 20);
    });
  });

  it('IMP06-AUDIT-04 · Consultar historia y organización archivada → conserva eventos y lectura autorizada', () => {
    cy.get<Context>('@audit').then((c) => {
      cy.task(
        'audit:snapshot',
        { organizationId: c.organizationId },
        { log: false },
      ).then((before) => {
        listReady(c);
        nextPage();
        cy.get(rows).should('have.length', 5);
        cy.task(
          'audit:snapshot',
          { organizationId: c.organizationId },
          { log: false },
        ).then((after) => expect(after).to.deep.equal(before));
      });
      cy.task(
        'audit:revoke',
        { organizationId: c.organizationId, actor: 'teacher' },
        { log: false },
      );
      listReady(c);
      cy.get('[name="actorId"]').type(c.teacherId);
      apply();
      cy.get(rows).should('have.length.greaterThan', 0);
      cy.get(rows).each(($row) => expect($row.text()).to.include(c.teacherId));
      cy.task(
        'audit:archive',
        { organizationId: c.organizationId },
        { log: false },
      );
      listReady(c);
      cy.contains('Organización archivada · Solo lectura.').should(
        'be.visible',
      );
      cy.get('[data-cy="audit-panel"]')
        .contains('button', /^(Crear|Editar|Archivar|Guardar|Eliminar)/)
        .should('not.exist');
    });
  });

  it('IMP06-AUDIT-05 · Respuesta tardía y caída de API → descarta datos anteriores y permite reintentar', () => {
    cy.get<Context>('@audit').then((c) => {
      let held = false;
      let aborted: AbortSignal | null | undefined;
      visitAs(c.admin, route(c), (window) => {
        const original = window.fetch.bind(window);
        window.fetch = (input, init) =>
          original(input, init).then((response) => {
            if (
              !held &&
              String(input).includes('/audit-events?') &&
              String(input).includes('action=fixture.updated') &&
              response.ok
            ) {
              held = true;
              aborted = init?.signal;
              return new Promise<Response>((resolve) => {
                releaseResponse = () => resolve(response);
              });
            }
            return response;
          });
      });
      cy.get(rows).should('have.length', 20);
      cy.get('[name="action"]').type('fixture.updated');
      apply();
      cy.wrap(null).should(() => expect(releaseResponse).to.be.a('function'));
      cy.get(rows).should('not.exist');
      clearFilters();
      cy.get(rows).should('have.length', 20);
      cy.then(() => {
        expect(aborted?.aborted).to.equal(true);
        releaseResponse!();
      });
      cy.get(rows).should('have.length', 20);
      cy.task('foundation:apiStop', null, { log: false });
      cy.contains('button', 'Actualizar auditoría').click();
      cy.get('[role="alert"]').should('be.visible');
      cy.get(rows).should('not.exist');
      cy.contains('No hay registros para estos filtros.').should('not.exist');
      cy.task('foundation:apiStart', null, { log: false });
      cy.contains('button', 'Reintentar consulta').click();
      cy.get(rows).should('have.length', 20);
    });
  });

  it('IMP06-AUDIT-06 · Recorrer filtros y tabla con teclado → foco y contenido legibles en tres tamaños', () => {
    cy.get<Context>('@audit').then((c) => {
      for (const size of [
        { name: 'desktop', width: 1440, height: 900 },
        { name: 'tablet', width: 768, height: 1024 },
        { name: 'mobile', width: 390, height: 844 },
      ]) {
        cy.viewport(size.width, size.height);
        listReady(c);
        cy.get('[data-cy="audit-filters"]').then(($form) => {
          cy.window().then((window) => {
            // Preserve the entire heading/form on narrow screens; the existing
            // table captures below retain their exact viewport dimensions.
            const bottom =
              $form[0]!.getBoundingClientRect().bottom + window.scrollY;
            cy.screenshot(`imp06-audit-filters-${size.name}`, {
              capture: 'fullPage',
              overwrite: true,
              clip: {
                x: 0,
                y: 0,
                width: size.width,
                height: Math.ceil(bottom),
              },
            });
          });
        });
        cy.get('[name="actorId"]').click();
        pressKeyInChrome('Tab');
        cy.get('[name="action"]').should('be.focused');
        pressKeyInChrome('Tab', true);
        cy.get('[name="actorId"]').should('be.focused');
        const table =
          '[role="region"][aria-label="Auditoría de la organización"]';
        tabTo(table);
        cy.get(table).should('be.focused').scrollIntoView();
        if (size.name === 'mobile') {
          for (let index = 0; index < 6; index++)
            pressKeyInChrome('ArrowRight');
          cy.get(table).should(($table) =>
            expect($table[0]!.scrollLeft).to.be.greaterThan(0),
          );
        }
        cy.document().should((document) =>
          expect(document.documentElement.scrollWidth).to.be.at.most(
            document.documentElement.clientWidth + 1,
          ),
        );
        cy.screenshot(`imp06-audit-${size.name}`, {
          capture: 'viewport',
          overwrite: true,
        });
        pressKeyInChrome('Tab');
        cy.focused().should('contain.text', 'Siguiente página');
        pressEnterInChrome();
        cy.get(rows).should('have.length', 5);
      }
    });
  });

  it('IMP06-AUDIT-07 · Cerrar sesión con una lectura pendiente y entrar como estudiante → no conserva datos administrativos', () => {
    cy.get<Context>('@audit').then((c) => {
      let held = false;
      let aborted: AbortSignal | null | undefined;
      visitAs(c.admin, route(c), (window) => {
        const original = window.fetch.bind(window);
        window.fetch = (input, init) =>
          original(input, init).then((response) => {
            if (
              !held &&
              String(input).includes('/audit-events?') &&
              String(input).includes('action=fixture.updated') &&
              response.ok
            ) {
              held = true;
              aborted = init?.signal;
              return new Promise<Response>((resolve) => {
                releaseResponse = () => resolve(response);
              });
            }
            return response;
          });
      });
      cy.get(rows).should('have.length', 20);
      cy.get('[name="action"]').type('fixture.updated');
      apply();
      cy.wrap(null).should(() => expect(releaseResponse).to.be.a('function'));
      cy.contains('button', 'Cerrar sesión').click();
      cy.get('[data-cy="audit-panel"]').should('not.exist');
      cy.then(() => {
        expect(aborted?.aborted).to.equal(true);
        releaseResponse!();
      });
      cy.get(rows).should('not.exist');
      cy.task<Session>('identity:login', 'STUDENT', { log: false }).then(
        (session) => {
          visitAs(session, route(c));
          cy.get('[role="alert"]').should('be.visible');
          cy.get(rows).should('not.exist');
        },
      );
    });
  });

  it('IMP06-AUDIT-08 · Abrir 10000 eventos entre dos organizaciones → primera navegación separada y 50 muestras p95 menor que 3 s', () => {
    cy.get<Context>('@audit').then((c) => {
      expect(c.oracle.total).to.equal(10000);
      expect(c.oracle.foreignTotal).to.equal(1000);
      const draft: Measurement = {
        organizationId: c.organizationId,
        firstNavigationMs: null,
        firstNavigationValid: false,
        samples: [],
        startedAt: null,
        index: 0,
      };
      cy.then(() => {
        measurement = draft;
      });
      for (let index = 0; index <= 50; index++) {
        cy.then(() => {
          draft.startedAt = performance.now();
          draft.index = index;
        });
        listReady(c);
        cy.then(() => {
          const durationMs = performance.now() - draft.startedAt!;
          draft.startedAt = null;
          if (index === 0) {
            draft.firstNavigationMs = durationMs;
            draft.firstNavigationValid = true;
          } else draft.samples.push({ durationMs, valid: true });
        });
      }
      cy.then(() => recordMeasurement(draft)).then((result) => {
        expect(result.samples).to.equal(50);
        expect(result.p95Ms).to.be.lessThan(3000);
        expect(result.passed).to.equal(true);
        measurement = null;
      });
    });
  });
});
